contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint am) public payable {
        uint beforeSenderBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;
        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool shouldEnter = beforeSenderBalance >= minSum && beforeSenderBalance >= am;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool unchanged = c.balances(address(this)) == beforeSenderBalance && address(c).balance == beforeContractBalance;
        bool decreased = c.balances(address(this)) + am == beforeSenderBalance && address(c).balance + am == beforeContractBalance;

        assert(shouldEnter ? (reverted || decreased) : (!reverted && unchanged));
    }

    receive() external payable {}
}

